const float angle = 1.;
const float speed = 200.;
const vec2 radius = vec2(75., 50.);

vec2 circle(float time) {
    vec2 fakeRes = iResolution.xy - radius*2.;

    vec2 move = vec2(cos(angle), sin(angle));
    vec2 pos = vec2(.5, .5)*fakeRes + move*(speed*time);

    pos.x = mod(pos.x, fakeRes.x*2.);
    pos.y = mod(pos.y, fakeRes.y*2.);

    // bounce
    if (pos.x > fakeRes.x) pos.x = fakeRes.x*2. - pos.x;
    if (pos.y > fakeRes.y) pos.y = fakeRes.y*2. - pos.y;

    // set anchor
    return pos + radius;
}

float sdf(vec2 pos, vec2 circle) {
    float dx = (pos.x-circle.x);
    float dy = (pos.y-circle.y) * radius.x / radius.y;

    return sqrt(dx*dx + dy*dy) - radius.x;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float acc = 0.;

    for (float i = 0.; i < 10.; i += 1.)
        acc += sdf(fragCoord.xy, circle(iTime - i/20.));

    float dist = acc/10.;

    float c = dist < -10. ? 1. : dist < 0. ? .5 + sqrt(-dist/10.)/2. : exp(-dist/50.-1.);
    fragColor = vec4(c, c, c, 1.);
}
